insert into public.ai_knowledge (kind, area, country_code, topic, title, summary, source_name, source_url, license, lang, status) values
('management','impuestos','MX','rfc_persona_moral_inscripcion','México: inscripción de una persona moral en el RFC (SAT)',
$k$El RFC se tramita ante el SAT. Para personas morales el SAT ofrece dos vías: con cita en una oficina del SAT (el trámite puede iniciarse con preinscripción en el portal) o, al firmar el acta constitutiva, a través de un fedatario público incorporado al esquema de inscripción por medios remotos. Documentos habituales: acta o documento constitutivo protocolizado (en las SAS, el contrato social emitido por la Secretaría de Economía), comprobante de domicilio fiscal, documento que acredite la representación legal e identificación oficial vigente del representante. Fuentes profesionales y de prensa (no oficiales) añaden que el comprobante puede estar a nombre de un socio, que la cita debe tomarse dentro de unos 10 días tras la preinscripción y que desde 2026 las SAS siguen el trámite de personas morales de la Resolución Miscelánea Fiscal con e.firma vigente de sus representantes; confirmar estos puntos en el SAT. El RFC es necesario para emitir facturas electrónicas (CFDI) y presentar declaraciones. Dónde confirmar: sat.gob.mx (fichas de trámite de inscripción en el RFC) y ventanillaunica.economia.gob.mx.$k$,
'Servicio de Administración Tributaria (SAT)','https://www.sat.gob.mx/gobmx/Paginas/ficha_45_cff.html',
'Material informativo del SAT, con apoyo de fuentes profesionales señaladas en el texto; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','impuestos','MX','efirma_solicitud_sat','México: e.firma (firma electrónica) del SAT, solicitud y uso',
$k$La e.firma es el certificado digital con el que personas físicas y morales firman trámites ante el SAT. Se solicita en una oficina del SAT o módulo de servicios tributarios que preste el servicio, previa cita registrada en el portal del SAT, SAT Móvil o gob.mx. Se obtiene el certificado, el comprobante de generación y los archivos .REQ y .KEY generados con el programa Certifica; la ficha de la persona moral es la 312/CFF y la de personas físicas la 105/CFF. Una copia del Diario Oficial de 2021 indica que la primera generación es gratuita; los requisitos y fichas cambian con cada Resolución Miscelánea Fiscal, por lo que debe confirmarse la ficha vigente. El representante legal debe tener e.firma vigente para varios trámites de personas morales. Guarde la clave privada: el SAT no puede recuperarla. Dónde confirmar: sat.gob.mx (ficha 105/CFF y 312/CFF) y el Anexo 1-A vigente.$k$,
'Servicio de Administración Tributaria (SAT)','https://www.sat.gob.mx/gobmx/Paginas/ficha_105_cff.html',
'Material informativo del SAT y DOF; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','legal','MX','registro_patronal_imss_alta','México: registro patronal ante el IMSS y obligaciones iniciales',
$k$Todo patrón con trabajadores subordinados debe registrarse ante el IMSS (alta patronal) y recibe un Número de Registro Patronal (NRP). El IMSS publica el trámite en modalidades según el tipo de patrón: una para personas físicas y otra para personas morales, sindicatos y retenedores de cuotas, y permite tramitarlo por internet. Con el NRP se registran trabajadores y se pagan cuotas obrero-patronales. Fuentes profesionales (no oficiales) indican que el alta de cada trabajador debe hacerse en un plazo de cinco días hábiles desde que inicia la relación laboral, que los movimientos (altas, bajas, cambios de salario) se envían con el sistema IDSE usando un certificado digital propio del IMSS, que el cálculo se apoya en el SUA y que conviene conservar nóminas y registros por al menos 5 años. También advierten que declarar salarios menores a los reales trae sanciones. Confirmar plazos y modalidades con el IMSS. Dónde confirmar: imss.gob.mx (trámite IMSS-02-001) y el portal IDSE.$k$,
'Instituto Mexicano del Seguro Social (IMSS)','https://www.imss.gob.mx/tramites/imss02001c',
'Material informativo del IMSS, con apoyo de fuentes profesionales señaladas en el texto; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','operacion','MX','prestaciones_laborales_lft','México: prestaciones mínimas de ley (aguinaldo, vacaciones, prima vacacional, PTU)',
$k$Según la PROFEDET, el aguinaldo debe pagarse antes del 20 de diciembre. La Ley Federal del Trabajo fija al menos 15 días de salario. Otras prestaciones mínimas que describen fuentes profesionales y de divulgación (confirmar en la ley vigente): vacaciones pagadas desde 12 días en el primer año tras la reforma de Vacaciones Dignas, con prima vacacional no menor al 25% sobre los salarios de esos días; reparto de utilidades (PTU) del 10% de las ganancias a los trabajadores; prima de antigüedad desde 15 años de servicio; aportaciones al IMSS, INFONAVIT y SAR. Los montos de salario mínimo y los topes de PTU cambian cada año; no se registran aquí. Los trabajadores pueden reclamar ante el Centro de Conciliación y la STPS/PROFEDET. Dónde confirmar: gob.mx/profedet, stps.gob.mx y el texto vigente de la Ley Federal del Trabajo en diputados.gob.mx.$k$,
'PROFEDET (gob.mx) y Ley Federal del Trabajo','https://www.gob.mx/cms/uploads/attachment/file/874276/PROFEDET_Preguntas_Frecuentes_Aguinaldo_2023.pdf',
'Material informativo de PROFEDET, con apoyo de fuentes profesionales señaladas en el texto; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','impuestos','EC','ruc_sociedades_sri_inscripcion','Ecuador: RUC de sociedades (SRI) y declaración de renta de sociedades',
$k$Las sociedades bajo control de la Superintendencia de Compañías o de la SEPS se inscriben en el RUC de forma coordinada entre esas entidades y el SRI: el proceso es automático una vez presentados los requisitos ante la superintendencia, salvo excepciones en que se debe ir presencialmente al SRI. Los requisitos generales son el documento que aprueba la creación, la solicitud de inscripción y actualización del RUC de sociedades, un documento que registre el establecimiento (domicilio) y el que acredite la representación legal. Hay requisitos alternativos para el canal presencial (pasaporte, licencia de conducir) y trámites en línea con clave del SRI para actualización, suspensión y cancelación. Las sociedades presentan la declaración del Impuesto a la Renta en el Formulario 102 por el portal del SRI. Una norma resuelve que quien no se inscribe puede ser inscrito de oficio, sin perjuicio de sanciones. Dónde confirmar: gob.ec/sri y sri.gob.ec (fichas de RUC persona jurídica).$k$,
'Servicio de Rentas Internas (SRI) vía gob.ec','https://www.gob.ec/sri/tramites/inscripcion-registro-unico-contribuyente-ruc-persona-juridica',
'Material informativo del SRI; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','legal','EC','sas_constitucion_superintendencia_companias','Ecuador: constituir una Sociedad por Acciones Simplificada (SAS)',
$k$La SAS se constituye ante la Superintendencia de Compañías, Valores y Seguros (no ante el Registro Mercantil), puede tener uno o más accionistas y no exige capital mínimo. Se empieza reservando el nombre en el portal de la superintendencia y luego se elige entre constitución electrónica, semielectrónica o por escritura. Datos y documentos: copia de cédula o pasaporte de accionistas, domicilio, contrato privado o escritura, nombramientos y, cuando corresponde, certificado electrónico del accionista. Según prensa económica (no oficial), una SAS puede crearse con USD 1 (el valor de una acción), tarda entre 2 y 5 días y las sociedades anónimas piden un capital mínimo de USD 800; confirmar estos valores. Terminada la constitución, la superintendencia comunica por correo la información de la compañía, y después se inscribe el RUC y el empleador en el IESS. Una SAS con actividades reguladas puede tener requisitos adicionales. Dónde confirmar: gob.ec/scvs y el portal de constitución de la superintendencia.$k$,
'Superintendencia de Compañías, Valores y Seguros (vía gob.ec)','https://www.gob.ec/scvs/tramites/constitucion-sociedades-acciones-simplificadas',
'Material informativo de la SCVS, con apoyo de prensa señalada en el texto; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','legal','EC','iess_obligaciones_empleador','Ecuador: obligaciones del empleador con el IESS y consecuencias de la mora',
$k$El empleador debe registrarse en el portal del IESS con su RUC o cédula y obtener clave. Según el IESS, debe afiliar al trabajador desde el primer día de labor, registrar el aviso de entrada dentro de los primeros 15 días, dar aviso de otras novedades y pagar las aportaciones dentro de los 15 días posteriores al mes al que corresponden. Si no paga, entra en mora patronal y puede enfrentar responsabilidad patronal; un fallo reciente indica que el IESS debe dar subsidio de maternidad y seguro de desempleo aun si el empleador está en mora. La prensa recuerda que retener aportes y no depositarlos en 90 días puede ser sancionado penalmente (COIP, prisión de uno a tres años) y que declarar menos sueldo del real es subdeclaración. Los porcentajes de aporte patronal y personal se fijan por resolución del IESS y cambian; confirmar la tabla vigente. Dónde confirmar: iess.gob.ec (empleadores), Ley de Seguridad Social y resoluciones del Consejo Directivo.$k$,
'Instituto Ecuatoriano de Seguridad Social (IESS)','https://www.iess.gob.ec/documents/10162/39761080/Pop_up_IESS_Sentencia_No_105-21-IN-25_23_abril_2026.pdf',
'Material informativo del IESS, con apoyo de prensa señalada en el texto; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','operacion','EC','decimos_fondo_reserva_utilidades','Ecuador: beneficios sociales del trabajador (décimos, fondo de reserva, utilidades)',
$k$En la nómina ecuatoriana se provisionan el décimo tercer sueldo, el décimo cuarto sueldo, el fondo de reserva y la participación de utilidades, además del aporte patronal al IESS. El IESS exige para ciertos trámites reportes de pago de décimos registrados en los mecanismos que determina el Ministerio del Trabajo. Los plazos de pago, las bases de cálculo, los montos del décimo cuarto (ligado al salario básico) y el porcentaje de utilidades no se registran aquí porque cambian o dependen del caso; deben confirmarse con el Ministerio del Trabajo y el contador antes de liquidar. Dónde confirmar: trabajo.gob.ec (sistema de salarios en línea) y iess.gob.ec.$k$,
'IESS y Ministerio del Trabajo del Ecuador','https://www.gob.ec/sites/default/files/sign/procedure-IESS-030-06-03-20260707222222-20113107-signed.pdf',
'Material informativo del IESS; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','impuestos','UY','inscripcion_unipersonal_rut_bps','Uruguay: inscribir una empresa unipersonal en DGI y BPS',
$k$En Uruguay la inscripción de la empresa unipersonal ante DGI y BPS (RUT) se hace en línea desde BPS Mis servicios en línea: Inscribir o reiniciar empresa, naturaleza Unipersonal, según actividad (comercial e industrial, servicio personal no profesional, monotributo común o monotributo social MIDES). Para el monotributo social MIDES, la autorización del MIDES no puede tener más de un año al inscribirse. También existe atención presencial con agenda previa en el sector RUT de la DGI en Montevideo, y para domicilios en el interior solo modalidad en línea. Si se presenta fuera de plazo hay multa de la DGI. Se usa el Formulario 0351 de inscripción y, si hay más de un local, el Formulario 0354. Una empresa cerrada puede reiniciarse por la web de BPS. Dónde confirmar: gub.uy/tramites (inscripción de empresa unipersonal), dgi.gub.uy y bps.gub.uy.$k$,
'Dirección General Impositiva y BPS (gub.uy)','https://www.gub.uy/tramites/inscripcion-empresa-unipersonal',
'Material informativo de gub.uy; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','legal','UY','inscripcion_sociedades_srl_y_hecho','Uruguay: inscripción de sociedades (SRL, colectiva, comandita) y sociedades de hecho',
$k$Las sociedades de hecho se inscriben por BPS Mis servicios en línea (actividad comercial e industrial o monotributo) y requieren la aprobación de todos los integrantes dentro de un plazo; si no la dan, la inscripción queda sin efecto y se debe ingresar una nueva. Para sociedades personales, contrato, colectiva, SRL, comandita simple y limitadas, se presenta el Formulario 0351, documento de identidad y, para SRL con soporte notarial electrónico, la documentación indicada; los representantes de SRL sin restricciones de actuación deben constituir domicilio electrónico ante BPS. Se accede con identidad digital o TuID/Abitab o se pide agenda en el sector RUT de DGI en Montevideo. Hay multa de DGI por presentación fuera de plazo. Dónde confirmar: gub.uy/tramites (inscripción de sociedad de hecho e inscripción de sociedad personal contrato) y dgi.gub.uy.$k$,
'Dirección General Impositiva (gub.uy)','https://www.gub.uy/tramites/inscripcion-sociedad-personal-contrato-colectiva-srl-comandita-simple-ltda',
'Material informativo de gub.uy; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','operacion','UY','aguinaldo_licencia_salario_vacacional','Uruguay: aguinaldo, licencia y salario vacacional (obligaciones del empleador)',
$k$El Ministerio de Trabajo y Seguridad Social (MTSS) explica que el aguinaldo es por definición la doceava parte de lo percibido en el período, que el salario vacacional se paga al salir de licencia y que los tickets de alimentación tienen naturaleza salarial, por lo que se cuentan para la licencia, el salario vacacional y la indemnización por despido, no para el aguinaldo. Un estudio profesional (Auren, 2022) agrega que el aguinaldo se paga antes del 20 de diciembre, que la licencia es de 20 días por año y que el salario vacacional no lleva descuentos; estos datos deben confirmarse en la normativa vigente. El MTSS también describe el recibo y la documentación salarial que el empleador debe poder exhibir a MTSS, BPS y BSE. Dónde confirmar: gub.uy/ministerio-trabajo-seguridad-social (Derecho laboral uruguayo: aguinaldo, salario vacacional, licencia).$k$,
'Ministerio de Trabajo y Seguridad Social (gub.uy)','https://www.gub.uy/ministerio-trabajo-seguridad-social/institucional/preguntas-frecuentes/materia-laboral',
'Material informativo del MTSS, con apoyo de fuente profesional señalada en el texto; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','finanzas','UY','bps_bonificaciones_micro_pequenas_empresas','Uruguay: bonificaciones de BPS a micro y pequeñas empresas por pago en fecha',
$k$BPS ha publicado bonificaciones a micro y pequeñas empresas que pagan sus aportes en fecha: un descuento del 15% en los aportes patronales jubilatorios de diciembre de 2024 y una bonificación del 10% en los de diciembre de 2025, anunciada en enero de 2026. En 2021 se aplicó una exoneración del 100% de aportes patronales jubilatorios a actividades afectadas por la emergencia sanitaria. Son medidas puntuales que cambian cada año y dependen de condiciones de tamaño y de estar al día; no asumir que se repetirán. Confirmar en la sección de novedades para empresas de BPS si corresponde a la empresa y qué requisitos hay. Dónde confirmar: bps.gub.uy (Novedades para empresas).$k$,
'Banco de Previsión Social (BPS)','https://www.bps.gub.uy/4813/novedades-para-empresas.html',
'Material informativo de BPS; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','legal','BR','abrir_cnpj_redesim_flujo','Brasil: flujo para abrir un CNPJ con Redesim (viabilidad, inscripción, licencia)',
$k$En Brasil el portal gov.br/Redesim organiza la apertura de empresa por etapas: primero la consulta de viabilidad (Paso 1 de Abrir CNPJ), luego la inscripción y, aparte, la alteración, el protocolo y el licenciamiento; el mismo portal ofrece ayuda sobre cada una y orientaciones por tipo de empresa (SA, cooperativa, startup) y el Inova Simples para empresas de innovación. El licenciamiento y varias exigencias dependen del municipio y del estado donde se instalará el negocio. Esta guía solo recoge la estructura del trámite: requisitos, costos y plazos por tipo societario no se registran aquí por no haberse verificado en página oficial. Dónde confirmar: gov.br/empresas-e-negocios (Redesim, Abrir CNPJ) y la junta comercial y la prefectura de su localidad.$k$,
'Redesim (gov.br Empresas e Negócios)','https://www.gov.br/empresas-e-negocios/pt-br/redesim/abrir-cnpj',
'Material informativo de gov.br; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','operacion','BR','mei_servicios_obligaciones','Brasil: servicios y obligaciones del Microemprendedor Individual (MEI)',
$k$El portal oficial del MEI agrupa los trámites de este régimen: emisión del comprobante de inscripción (CCMEI), declaración anual de facturación (DASN-SIMEI), pago de la contribución mensual y parcelamientos, contratación de empleado, baja de la empresa, transición del MEI a microempresa (desenquadramento) y certificaciones. No se registran aquí límites de facturación ni valores de la contribución porque cambian; deben consultarse en el portal. Dónde confirmar: gov.br/empresas-e-negocios (Serviços para MEI) y el Portal del Emprendedor.$k$,
'Portal do Empreendedor (gov.br)','https://www.gov.br/redesim',
'Material informativo de gov.br; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft'),
('management','legal','BR','esocial_obligaciones_empleador','Brasil: eSocial, FGTS y 13º salario como obligaciones del empleador',
$k$El eSocial es el sistema federal que unifica el envío de información del empleador sobre sus trabajadores: obligaciones fiscales, laborales, previsionales y de FGTS; lo gestionan Caixa (FGTS), Ministerio de Trabajo, INSS y Receita Federal. El acceso se hace con cuenta gov.br; el portal avisa que se exige nivel oro o plata. Los manuales del eSocial describen el registro de vínculos, la nómina, vacaciones y el 13º salario (anticipo y segunda cuota). Para el empleador doméstico existe un módulo simplificado con guía única de pago (DAE). Alícuotas, plazos de pago y multas no se registran aquí; confirmarlas en el portal y con el contador laboral. Dónde confirmar: gov.br/esocial, caixa.gov.br (FGTS) y gov.br/inss.$k$,
'eSocial (gov.br) y Caixa Econômica Federal','https://www.gov.br/esocial/pt-br',
'Material informativo de gov.br y Caixa; no declara licencia abierta. Resumido con palabras propias, con enlace a la fuente. Pendiente de confirmación con contador.','es','draft');